initPrintingIconsObserver(){
  try {
    if (this._pIconsObs) {
      try { this._pIconsObs.disconnect(); } catch(e){}
      this._pIconsObs = null;
    }
    if (this.activePanel !== 'graphics') return;
    if (this.zone && this.zone.runOutsideAngular) {
      this.zone.runOutsideAngular(() => {
        this._pIconsObs = new MutationObserver(() => {
          if (this.activePanel === 'graphics' && !document.getElementById('dsgn-custom-print-icons')) {
            this.attachPrintingIconCategories();
          }
        });
        let spTarget = document.querySelector('.dsgn-side-panel');
        if (spTarget) this._pIconsObs.observe(spTarget, { childList: true, subtree: false });
      });
    }
  } catch(e) {}
}

